"""End-to-end smoke test on synthetic data (schema-compatible, generated by tests/synth.py)."""
import os

import pandas as pd
import yaml

import run_pipeline
import synth

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def test_pipeline_end_to_end(tmp_path):
    synth.generate(str(tmp_path / "data"), n_matches=260, seed=1)
    cfg = yaml.safe_load(open(os.path.join(ROOT, "config.yaml")))
    cfg["eligibility"].update(batter_min_pressure_balls=40, bowler_min_pressure_balls=40, min_pressure_matches=5)
    cfg["reliability"]["bootstrap_resamples"] = 30
    cfg["models"]["n_folds"] = 3
    cp = tmp_path / "config.yaml"
    yaml.safe_dump(cfg, open(cp, "w"))
    out = tmp_path / "out"
    assert run_pipeline.main(["--config", str(cp), "--data-dir", str(tmp_path / "data"), "--output-dir", str(out)]) == 0
    truth = pd.read_csv(tmp_path / "data" / "_truth.csv").set_index("player_id")
    for name, skill in [("batters", "bat_skill"), ("bowlers", "bowl_skill")]:
        top = pd.read_csv(out / f"top10_{name}.csv")
        assert len(top) == 10 and top["rank"].tolist() == sorted(top["rank"]) and top["player_id"].is_unique
        full = pd.read_csv(out / f"{name}_ranked_full.csv").set_index("player_id").join(truth)
        assert full["eligible"].all()
        assert {"rating", "z_pressure", "z_lift", "z_consistency", "pressure_balls", "pressure_value_ci_low",
                "rank_boot_low", "rank_boot_high", "teams", "player_name"} <= set(full.columns)
        # value must point the right way: better true skill -> higher measured value
        assert full["nonpressure_value_per_ball_adj"].corr(full[skill]) > 0.2
        assert full["pressure_value_per_ball_adj"].corr(full[skill]) > 0
    assert (out / "methodology_report.md").exists()
    assert len(list((out / "charts").glob("*.png"))) >= 12
